// Single design per execution — just pass it through
const raw = $input.first().json;
const design = raw.concept || raw;
const niche = raw.niche || design.niche || '';
return [{ json: { niche, ...design } }];

const ctx = $('Split Designs').first().json;
const raw = $input.first().json?.choices?.[0]?.message?.content || '{}';
const clean = raw.replace(/```json|```/g, '').trim();
const match = clean.match(/\{[\s\S]*\}/);
let seo = {};
try { seo = JSON.parse(match?.[0] || '{}'); } catch (_) {}

return [{
  json: {
    ...ctx,
    etsyTitle:          seo.etsyTitle          || '',
    etsyDescription:    seo.etsyDescription    || '',
    etsyTags:           seo.etsyTags           || [],
    amazonTitle:        seo.amazonTitle        || '',
    amazonBulletPoints: seo.amazonBulletPoints || [],
    amazonKeywords:     seo.amazonKeywords     || '',
    seoFileName:        seo.fileName           || '',
    altText:            seo.altText            || '',
    searchTerms:        seo.searchTerms        || []
  }
}];
